            ['start_time'=>246.84,'end_time'=>248.02,'target_text'=>'3,000.','source_text'=>'3,000.','order'=>88],
            ['start_time'=>248.12,'end_time'=>253.46,'target_text'=>'That is the amount of words you need to understand up to 95%','source_text'=>'Itulah jumlah perkataan yang anda perlukan untuk memahami sehingga 95%','order'=>89],
