            ['start_time'=>1250.48,'end_time'=>1251.58,'target_text'=>'So, let\'s get a grab.','source_text'=>'Jadi jom kita tempah Grab Bike dan pulang.','order'=>560],
            ['start_time'=>1251.68,'end_time'=>1252.62,'target_text'=>'Let\'s get out of here.','source_text'=>'Jom kita beredar dari sini.','order'=>561],
