            ['start_time'=>736.36,'end_time'=>738.9,'target_text'=>'He crashed out after losing the game.','source_text'=>'Dia mengamuk hilang sabar lepas kalah perlawanan tadi (crashed out).','order'=>210],
            ['start_time'=>739,'end_time'=>741.7,'target_text'=>'Don\'t crash out over one bad comment.','source_text'=>'Janganlah sampai mengamuk tak tentu pasal semata-mata sebab satu komen negatif.','order'=>211],
            ['start_time'=>741.8,'end_time'=>746.26,'target_text'=>'So, use it when describing someone overreacting emotionally.','source_text'=>'Gunakan bila menggambarkan seseorang yang terlebih beremosi sehingga hilang sabar.','order'=>212],
            ['start_time'=>746.36,'end_time'=>748.22,'target_text'=>'Number 20, flex.','source_text'=>'Nombor 20, \'flex\'.','order'=>213],
