            ['start_time'=>377.52,'end_time'=>379.78,'target_text'=>'That\'s Bro, that is so much for a coffee.','source_text'=>'Biar betul bro, mahalnya harga kopi tu.','order'=>165],
            ['start_time'=>379.88,'end_time'=>381.06,'target_text'=>'$5.96.','source_text'=>'$5.96.','order'=>166],
            ['start_time'=>381.16,'end_time'=>382.1,'target_text'=>'Oh, Iced Capp, dude.','source_text'=>'Oh, ada Iced Capp.','order'=>167],
            ['start_time'=>382.2,'end_time'=>384.34,'target_text'=>'These are so good at in Canada.','source_text'=>'Air ni memang sedap gila kat Kanada.','order'=>168],
            ['start_time'=>384.44,'end_time'=>385.54,'target_text'=>'The original Iced Capp is fire.','source_text'=>'Iced Capp original memang mantap.','order'=>169],
            ['start_time'=>385.64,'end_time'=>387.58,'target_text'=>'Honestly, I might get the original Iced Capp.','source_text'=>'Sejujurnya, saya rasa nak ambil Iced Capp original.','order'=>170],
