            ['start_time'=>389.8,'end_time'=>390.82,'target_text'=>'Beverages.','source_text'=>'Minuman.','order'=>172],
            ['start_time'=>390.92,'end_time'=>392.94,'target_text'=>'>> What do they got for merch and donuts?','source_text'=>'>> Barangan cenderamata dan donat apa yang dorang jual?','order'=>173],
            ['start_time'=>393.04,'end_time'=>394.1,'target_text'=>'>> Merchandise.','source_text'=>'>> Cenderamata.','order'=>174],
            ['start_time'=>394.2,'end_time'=>396.3,'target_text'=>'Maple candle, $36.','source_text'=>'Lilin wangi mapel, $36.','order'=>175],
