            ['start_time'=>799.96,'end_time'=>800.78,'target_text'=>'What are you buying?','source_text'=>'Kau tengah beli apa tu?','order'=>309],
            ['start_time'=>800.88,'end_time'=>801.9,'target_text'=>'>> Buying these chips here.','source_text'=>'>> Beli kerepek ni.','order'=>310],
