            ['start_time'=>579.56,'end_time'=>579.96,'target_text'=>'>> Yeah.','source_text'=>'Ya, nak.','order'=>238],
            ['start_time'=>580.04,'end_time'=>581.34,'target_text'=>'How long have you been learning English?','source_text'=>'Dah berapa lama awak belajar bahasa Inggeris?','order'=>239],
            ['start_time'=>581.44,'end_time'=>583.74,'target_text'=>'>> I\'m learning English for three months.','source_text'=>'Saya dah belajar bahasa Inggeris selama tiga bulan.','order'=>240],
            ['start_time'=>583.84,'end_time'=>584.24,'target_text'=>'Three months?','source_text'=>'Tiga bulan?','order'=>241],
            ['start_time'=>584.32,'end_time'=>585.94,'target_text'=>'>> Uh through your video.','source_text'=>'Melalui video-video awak.','order'=>242],
            ['start_time'=>586.04,'end_time'=>586.66,'target_text'=>'For three months?','source_text'=>'Selama tiga bulan?','order'=>243],
            ['start_time'=>586.76,'end_time'=>587.18,'target_text'=>'>> Uh three months.','source_text'=>'Ya, tiga bulan.','order'=>244],
