            ['start_time'=>592.56,'end_time'=>594.22,'target_text'=>'Okay, cuz your pronunciation is good.','source_text'=>'Baguslah, sebab sebutan awak memang jelas dan elok.','order'=>250],
            ['start_time'=>594.32,'end_time'=>596.3,'target_text'=>'>> I\'m playing your video.','source_text'=>'Saya tonton video awak.','order'=>251],
            ['start_time'=>596.4,'end_time'=>596.8,'target_text'=>'Yeah.','source_text'=>'Ya.','order'=>252],
            ['start_time'=>596.8,'end_time'=>598.86,'target_text'=>'And uh speaking, uh, shadowing?','source_text'=>'Dan bertutur sambil buat teknik shadowing?','order'=>253],
            ['start_time'=>598.96,'end_time'=>601.22,'target_text'=>'Shadowing as I speak.','source_text'=>'Meniru apa yang saya cakap sambil buat shadowing.','order'=>254],
            ['start_time'=>601.32,'end_time'=>602.34,'target_text'=>'Are you in university?','source_text'=>'Awak masih belajar kat universiti ke?','order'=>255],
            ['start_time'=>602.44,'end_time'=>603.42,'target_text'=>'Are you in school?','source_text'=>'Masih bersekolah lagi?','order'=>256],
            ['start_time'=>603.52,'end_time'=>604.18,'target_text'=>'Are you working?','source_text'=>'Atau dah bekerja?','order'=>257],
            ['start_time'=>604.28,'end_time'=>606.3,'target_text'=>'>> uh, my one business.','source_text'=>'Saya ada perniagaan sendiri.','order'=>258],
            ['start_time'=>606.4,'end_time'=>607.18,'target_text'=>'Oh, you have a business?','source_text'=>'Oh, awak ada bisnes sendiri?','order'=>259],
            ['start_time'=>607.28,'end_time'=>607.68,'target_text'=>'Oh, nice.','source_text'=>'Wah, hebatnya.','order'=>260],
