            ['start_time'=>614.64,'end_time'=>615.3,'target_text'=>'>> You have an e-commerce brand.','source_text'=>'Awak ada jenama e-dagang sendiri.','order'=>266],
            ['start_time'=>615.4,'end_time'=>615.98,'target_text'=>'What do you sell?','source_text'=>'Produk apa yang awak jual?','order'=>267],
