            ['start_time'=>724.16,'end_time'=>724.62,'target_text'=>'Mhm.','source_text'=>'Mhm.','order'=>328],
            ['start_time'=>724.72,'end_time'=>726.78,'target_text'=>'I think you love camping.','source_text'=>'Saya rasa awak memang suka aktiviti berkhemah.','order'=>329],
            ['start_time'=>726.88,'end_time'=>727.2,'target_text'=>'Mhm.','source_text'=>'Mhm.','order'=>330],
            ['start_time'=>727.2,'end_time'=>727.62,'target_text'=>'I do.','source_text'=>'Ya, saya memang suka.','order'=>331],
            ['start_time'=>727.72,'end_time'=>727.96,'target_text'=>'Yeah.','source_text'=>'Ya.','order'=>332],
            ['start_time'=>727.96,'end_time'=>730.7,'target_text'=>'A camping site very nice.','source_text'=>'Tapak perkhemahan tu sangat cantik.','order'=>333],
            ['start_time'=>730.8,'end_time'=>731,'target_text'=>'Yeah.','source_text'=>'Ya, betul.','order'=>334],
            ['start_time'=>731,'end_time'=>731.78,'target_text'=>'Have you been camping?','source_text'=>'Awak pernah pergi berkhemah tak?','order'=>335],
            ['start_time'=>731.88,'end_time'=>733.18,'target_text'=>'I don\'t have experience.','source_text'=>'Saya belum ada pengalaman berkhemah lagi.','order'=>336],
            ['start_time'=>733.28,'end_time'=>735.42,'target_text'=>'Uh, is it popular in Korea to go camping?','source_text'=>'Aktiviti berkhemah ni popular ke kat Korea?','order'=>337],
            ['start_time'=>735.52,'end_time'=>738.78,'target_text'=>'Uh, camping, uh, this year, camping is very popular.','source_text'=>'Tahun ini aktiviti berkhemah memang sangat popular di Korea.','order'=>338],
            ['start_time'=>738.88,'end_time'=>742.54,'target_text'=>'But, after winter, popularity is going down.','source_text'=>'Tapi lepas habis musim sejuk, sambutannya mula menurun.','order'=>339],
            ['start_time'=>742.64,'end_time'=>743.04,'target_text'=>'Going down.','source_text'=>'Mula berkurangan.','order'=>340],
            ['start_time'=>743.08,'end_time'=>743.9,'target_text'=>'Yeah, same in Canada.','source_text'=>'Ya, sama juga keadaannya di Kanada.','order'=>341],
            ['start_time'=>744,'end_time'=>749.14,'target_text'=>'In Canada, spring to fall, but in winter, it\'s minus like 40 in Canada.','source_text'=>'Di Kanada orang berkhemah dari musim bunga sampai musim luruh, tapi masa musim sejuk suhunya mencecah tolak 40 darjah.','order'=>342],
