            ['start_time'=>842.96,'end_time'=>844.54,'target_text'=>'Like, No, it\'s really good.','source_text'=>'Memang sangat bagus sebenarnya.','order'=>387],
            ['start_time'=>844.64,'end_time'=>847.78,'target_text'=>'I\'ve been in Korea 26 days, almost a month.','source_text'=>'Saya dah berada di Korea selama 26 hari, hampir sebulan.','order'=>388],
