            ['start_time'=>861.28,'end_time'=>862.7,'target_text'=>'Kesan kedut yang dalam pada bahagian kulit.','source_text'=>'Deep creases in the leather.','order'=>283],
            ['start_time'=>862.8,'end_time'=>864.06,'target_text'=>'Kasut ni daripada kulit.','source_text'=>'These shoes are leather.','order'=>284],
            ['start_time'=>864.16,'end_time'=>866.06,'target_text'=>'Kulit ialah jenis bahannya.','source_text'=>'Leather is the material.','order'=>285],
            ['start_time'=>866.16,'end_time'=>869.42,'target_text'=>'Tapi kasut ni dah agak lama dan ada kesan kotoran tompok.','source_text'=>'But they\'re pretty old and they\'re also stained.','order'=>286],
            ['start_time'=>869.52,'end_time'=>871.58,'target_text'=>'Dulu bahagian ni semua warna putih.','source_text'=>'Before this was all white.','order'=>287],
